head.script:
scwin.checkVal = function() {
    return WebSquare.wUnit.getObjById("grd_t01_cell_0_1").textContent == '부산[CM]센터$ . [ ] ^  + { } ( )';
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_t01_temp_id_4859_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_t01_customFilter_list').querySelectorAll('div')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_t01_customFilter_list').querySelectorAll('div')[2].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_t01_temp_id_4859_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grd_t01_body_tbody tr').not('.w2grid_hidedRow').length == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    dsl_asgnCntr3.setJSON([{
        "oparam1": "aa",
