    }, {
        "oparam1": "bb",
        "oparam2": "대구[CM]센터B"
    }]);
    dsl_mgType.setJSON([{
        "oparam1": "C10",
        "oparam2": "정지전"
    }, {
        "oparam1": "C40",
        "oparam2": "특이"
    }, {
        "oparam1": "C42",
        "oparam2": "고액정보료특이"
    }]);
    dst_t01_out01.setJSON([{
        "check_ind": "0",
        "asgn_cntr": "aa",
        "col_mg_typ_cd": "C40"
    }, {
        "check_ind": "0",
        "asgn_cntr": "bb",
        "col_mg_typ_cd": "C40"
    }]);
    //Function unitTest
    //Create buy Truong.Luu
